oracleReaderQuery.value:
@concat(
    if(
        contains(pipeline().parameters.SourceQuery, '[watermark]'),
        replace(
            pipeline().parameters.SourceQuery,
            '[watermark]',
            replace(activity('Lookup Previous Watermark Value finsight').output.firstRow.WatermarkValue, 'T', ' ')
        ),
        concat(
            pipeline().parameters.SourceQuery,
            ' and ',
            pipeline().parameters.SourceTableName, '.', pipeline().parameters.WaterMarkColumnName,
            ' > TO_DATE(SUBSTR(''',
                replace(activity('Lookup Previous Watermark Value finsight').output.firstRow.WatermarkValue, 'T', ' '),
            ''', 1, 19), ''YYYY-MM-DD HH24:MI:SS'')'
        )
    )
)

